mapper.select:
SELECT account_id,housing_management_id,city_name,housing_title,address,group_name, file_name,rent,state,housing_mode_id,room,hall,mode,see FROM housing_user u,housing_management h,housing_mode m WHERE
account_id = #{accountId} AND
u.housing_management_id = h.id AND h.housing_mode_id = m.id LIMIT #{page},#{record};

SELECT account_id,housing_management_id,city_name,housing_title,address,group_name, file_name,rent,state,housing_mode_id,room,hall,MODE,see FROM housing_user u,housing_management h,housing_mode m WHERE u.housing_management_id = h.id AND h.housing_mode_id = m.id
AND account_id LIKE "%"#{accountId}"%"
LIMIT #{page},#{rows};

SELECT
    account_id,housing_management_id,city_name,housing_title,address,
    group_name,file_name,rent,state,housing_mode_id,room,hall,MODE,see
FROM
    housing_user u,housing_management h,housing_mode m
WHERE
    u.housing_management_id = h.id AND h.housing_mode_id = m.id

        AND h.housing_mode_id IN (

            #{mode}

        )


        AND h.rent BETWEEN #{hScreen.rentMin} AND #{hScreen.rentMax}


        AND h.room = #{hScreen.room} AND h.hall = #{hScreen.hall}


        AND h.city_name = #{hScreen.cityName}


        AND h.housing_title LIKE "%"#{hScreen.housingTitle}"%"


        ORDER BY h.rent ${hScreen.Sort}

LIMIT #{page},#{record};
